import {newProject,readProjects} from './projects.js';
import {shareProject,acceptancePanel} from './sharing.js';
import {createCloud,mountCloud} from './cloud.js';
import {agreementBlob,agreementHtml} from './agreement.js';
import{example,stages,clientProject,encode,decode,validate,deliverableItems,defaultChangesPolicy}from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const guestKey='seabird-workspace-v2';let key=guestKey,workspace=null,sharedRecord=null,view='projects';const proposalToken=location.hash.startsWith('#proposal=')?location.hash.slice(10):null;let projects=[],p,preview=false,readonly=!!proposalToken||location.hash.startsWith('#project='),storageOK=true;const dialog=$('#dialog');
if(proposalToken){
  try{await loadPublished();}catch(error){$('#app').innerHTML='<section class="error"><h1>This link is unavailable.</h1><p>'+esc(error.message)+'</p><p>Ask Roll for a current link.</p><button onclick="location.reload()">Try again</button></section>';throw error;}
}else if(readonly){try{p=decode(location.hash.slice(9))}catch{ $('#app').innerHTML='<section class="error"><h1>This link is incomplete.</h1><p>Ask Roll for a fresh project link.</p></section>';throw Error('Invalid shared project');}}
else{readDraft();}
function readDraft(){try{projects=readProjects(localStorage,key);}catch{projects=[];storageOK=false;}p=projects[0];}
function setAccount(id){key=id?'seabird-workspace-user:'+id:guestKey;readDraft();preview=false;view='projects';save();}
async function loadPublished(){const record=await createCloud().read(proposalToken);if(!record||!validate(record.project))throw Error('The link may have been revoked.');sharedRecord=record;p=record.project;}
async function reloadPublished(){await loadPublished();render();}

function money(n){return new Intl.NumberFormat('en-NZ',{style:'currency',currency:p.currency,maximumFractionDigits:0}).format(n)}function date(s){return new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'})}function save(){if(readonly)return;try{localStorage.setItem(key,JSON.stringify(projects));storageOK=true}catch{storageOK=false;toast('Storage is full or unavailable. Export a backup to keep this project.')}render();workspace?.changed()}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function render(){if(!readonly&&(view==='projects'||!p)){renderProjects();return;}if(!readonly&&p.changesPolicy===undefined)p.changesPolicy=defaultChangesPolicy;const client=readonly||preview,s=stages(p),end=s.at(-1).end;document.title=`${p.title} — Seabird`;$('#actions').innerHTML=readonly?'':preview?'<button data-action="preview">← Back to editing</button><button class="primary" data-action="share">Share project ↗</button>':'<button data-action="projects">Projects</button><button data-action="preview">Client view</button><button class="primary" data-action="share">Share project ↗</button>';
$('#actions').insertAdjacentHTML('afterbegin','<button data-action="agreement">Agreement</button>');
$('#app').innerHTML=`${preview?'<div class="preview-banner">Client preview · your internal pricing is hidden</div>':''}<div class="meta"><span>Roll &nbsp; / &nbsp; For ${esc(p.client)}</span><span class="status"><i class="dot"></i>${sharedRecord?(sharedRecord.accepted_at?'Accepted · version '+sharedRecord.version:'Published · version '+sharedRecord.version):readonly?'Project proposal':'Draft proposal'}</span></div><div class="intro"><div><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p></div>${!client?'<button data-action="project">Edit project ↗</button>':''}</div><section class="timeline-card" aria-label="Project timeline"><div class="timeline-heading"><span class="section-label">The plan, in one line</span><span>${date(p.start)} — ${date(end)} · working days</span></div><div class="timeline-scroll"><div class="timeline">${s.map((v,i)=>`<button class="stage" data-stage="${i}" style="--stage:${v.color};flex:${Math.max(1,Math.min(3,(new Date(v.end)-new Date(v.start))/86400000/3))}" aria-label="${esc(v.name)}, ${date(v.start)} to ${date(v.end)}. View details"><span class="date">${date(v.start)}</span><span class="bar"></span><strong>${esc(v.name)}</strong><small>${esc(v.owner)}</small></button>`).join('')}</div></div><div class="timeline-note"><span class="legend"><i></i>Making</span><span class="legend"><i></i>Reviewing</span><span style="margin-left:auto">Click a moment for the details ↗</span></div></section><section class="overview"><div class="scope"><span class="section-label">What we're making</span><h2>A beginning worth watching.</h2><p>${esc(deliverableItems(p)[0]?.name||'Deliverables to be agreed')}</p><div class="tags"><span class="tag">${p.reviews} review rounds</span><span class="tag">${p.reviewDays} working days per review</span><span class="tag">${date(end)} delivery</span></div></div><div class="price"><span class="section-label">Project fee</span><div class="amount">${money(p.fee)}<small>${p.currency}</small></div><p>${esc(p.tax)} · ${p.deposit}% to get started</p>${!client?'<button class="text-button" data-action="pricing">Work out the price ↗</button>':'<span class="hint">Payment details below ↓</span>'}</div></section><section class="rows">
${row('01','The deliverables','What’s included',deliverableItems(p).map(v=>`<div class="deliverable"><b>${esc(v.name)}</b><p>${esc(v.specs||'Technical specifications to be agreed.')}</p></div>`).join(''),client?'':'scope')}
${row('02','Reviews & timing',`${p.reviews} rounds · ${p.reviewDays} days each`,`<b>${p.reviews} review rounds, with ${p.reviewDays} working days for each.</b>\nOne consolidated set of feedback per round. Dates run Monday–Friday; public holidays are not excluded.\n\n${s.map(v=>`${esc(v.name)}: ${date(v.start)}${v.end!==v.start?' – '+date(v.end):''} · ${esc(v.owner)}`).join('\n')}`,client?'':'schedule')}
${row('03','What we need from you',`By ${date(p.start)}`,`<b>${esc(p.client)} to supply by kick-off:</b>\n${esc(p.inputs)}`,client?'':'inputs')}
${row('04','Payments',`${p.deposit}% now · ${100-p.deposit}% at delivery`,`<div class="payment"><span><b>01 &nbsp; To book the project</b><br>${date(p.start)} · ${p.deposit}%</span><b>${money(Math.round(p.fee*p.deposit/100))}</b></div><div class="payment"><span><b>02 &nbsp; Before final masters</b><br>${date(end)} · ${100-p.deposit}%</span><b>${money(p.fee-Math.round(p.fee*p.deposit/100))}</b></div><p>${esc(p.paymentNote)}</p>`,client?'':'payments')}
${row('05','The working agreement','The small, important things',`${esc(p.terms)}\n\n<b>Usage & handover</b>\n${esc(p.rights)}`,client?'':'terms')}
${row('06','Changes & delays','When the plan changes',esc(p.changesPolicy??'No separate changes policy was specified in this version. Please refer to the working agreement.'),client?'':'changes')}</section><div class="bottom-note"><span class="asterisk">✳</span><span>${sharedRecord?'Review all details, then record your acceptance below.':readonly?'This is a proposal snapshot. Please confirm the scope, dates and terms with Roll before work begins.':'Everything in one place. Open a card to fine-tune the details, then preview what your client sees.'}</span></div>`;
$('#save-state').textContent=readonly?(sharedRecord?'Published version '+sharedRecord.version+' · shared by Roll':'Project snapshot · shared by Roll'):storageOK?'Roll workspace · saved on this device':'Storage unavailable · export a backup';if(sharedRecord)$('#app').append(acceptancePanel({cloud:createCloud(),token:proposalToken,record:sharedRecord,reload:reloadPublished}));}
function row(n,title,summary,body,edit){
const descriptions={'01':'The items we will deliver, and their technical specifications.','02':'When we make, when you review, and when it is ready.','03':'The files and information we need to get started.','04':'How much is due, and when to pay it.','05':'Scope, usage and the terms we agree to.','06':'How we handle changes, moving dates and late inputs.'};
const icons={'01':'▤','02':'◷','03':'↓','04':'$','05':'≡','06':'↔'};
return `<details class="project-card" name="project-sections"><summary><span class="card-top"><span class="card-icon" aria-hidden="true">${icons[n]}</span><span class="num">${n}</span></span><span class="row-title">${title}</span><span class="card-description">${descriptions[n]}</span><span class="card-bottom"><span class="row-summary">${summary}</span><span class="plus">+</span></span></summary><div class="detail">${body}${edit?`<br><button data-action="${edit}">Edit details ↗</button>`:''}</div></details>`}
const field=(name,label,type='text',value=p[name],attrs='')=>`<label for="${name}">${label}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" maxlength="10000">${esc(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs} required>`}`;
const num=(name,label,min=0,max=1000000)=>field(name,label,'number',p[name],`min="${min}" max="${max}" step="${['reviews','conceptDays','animationDays','reviewDays','finishDays'].includes(name)?1:0.01}"`);
function open(title,html,onSubmit,button='Save changes ↗'){ $('#dialog-title').textContent=title;$('#fields').innerHTML=html;$('#submit').textContent=button;$('#submit').hidden=!onSubmit;$('#form').onsubmit=e=>{e.preventDefault();if(onSubmit)onSubmit(new FormData(e.target))};dialog.showModal()}
function edit(kind){if(kind==='scope'){editDeliverables();return}let html='',title='';switch(kind){case'project':title='The project';html=field('title','Project name','text',p.title,'maxlength="200"')+field('client','Client','text',p.client,'maxlength="200"')+field('description','One-line description');break;case'scope':title='What’s included';html=field('deliverables','Deliverables · one per line','textarea');break;case'inputs':title='What the client supplies';html=field('inputs','Materials due at kick-off · one per line','textarea');break;case'changes':title='Changes & delays';html=field('changesPolicy','How we handle changes and delays','textarea');break;case'terms':title='The working agreement';html=field('terms','Commercial terms','textarea')+field('rights','Usage, licences & source files','textarea');break;case'payments':title='When you get paid';html=num('deposit','Deposit (%)',0,100)+field('paymentNote','Payment terms','textarea')+field('tax','Tax wording');break;case'schedule':title='Make room for good work';html=field('start','Kick-off date','date')+'<div class="pair"><div>'+num('conceptDays','Direction (working days)',1,90)+'</div><div>'+num('animationDays','Animation (working days)',1,90)+'</div></div><div class="pair"><div>'+num('reviews','Review rounds',1,6)+'</div><div>'+num('reviewDays','Days for each review',1,90)+'</div></div>'+num('finishDays','Refinement / delivery days',1,90)+'<p class="hint">Changing a duration moves later stages automatically. Weekends are skipped; public holidays are not. Review 1 follows direction; later reviews follow animation.</p>';break;case'pricing':title='A price that adds up';html='<p class="hint">Only you see the working numbers. Your client sees the agreed project fee.</p><div class="pair"><div>'+num('rate','Day rate')+'</div><div>'+num('days','Estimated days',0.5,1000)+'</div></div>'+num('costs','Other costs')+'<div class="calc"><span>Working estimate</span><b id="estimate"></b></div>'+num('fee','Agreed project fee')+'<label for="currency">Currency</label><select id="currency" name="currency">'+['NZD','USD','AUD','GBP','EUR'].map(c=>`<option ${p.currency===c?'selected':''}>${c}</option>`).join('')+'</select>'+field('tax','Tax wording');break}
open(title,html,data=>{const next={...p};for(const[k,v]of data)next[k]=['rate','days','costs','fee','deposit','reviews','conceptDays','animationDays','reviewDays','finishDays'].includes(k)?Number(v):v.trim();if(!next.title||!next.client||!validate(next)){toast('Please check your project details.');return}Object.assign(p,next);save();dialog.close();toast('Project updated')});if(kind==='pricing'){const update=()=>$('#estimate').textContent=money(Number($('#rate').value)*Number($('#days').value)+Number($('#costs').value));['rate','days','costs'].forEach(k=>$('#'+k).addEventListener('input',update));update()}}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function share(){shareProject({workspace,project:p,open,toast,download}).catch(error=>toast(error.message));}
function projectList(){view='projects';preview=false;if(dialog.open)dialog.close();render();window.scrollTo(0,0);}
function renderProjects(){
 document.title='Your projects — Seabird';
 $('#actions').innerHTML='<button class="primary" data-action="new">+ New project</button>';
 $('#app').innerHTML='<section class="projects-home"><div class="intro"><div><span class="section-label">YOUR WORKSPACE</span><h1>Your projects</h1><p>From the first idea to the agreed plan. All your projects, together.</p></div><span class="project-count">'+projects.length+' project'+(projects.length===1?'':'s')+'</span></div>'+(projects.length?'<div class="project-grid">'+projects.map((item,i)=>'<button class="project-tile" data-project="'+i+'"><span class="project-client">'+esc(item.client)+'</span><h2>'+esc(item.title)+'</h2><p>'+esc(item.description||'Scope, schedule and agreement')+'</p><span class="project-tile-meta"><span>'+new Intl.NumberFormat('en-NZ',{style:'currency',currency:item.currency,maximumFractionDigits:0}).format(item.fee)+' '+item.currency+'</span><span>Kick-off '+date(item.start)+'</span></span><span class="project-open">Open project ↗</span></button>').join('')+'</div>':'<div class="projects-empty"><span class="empty-symbol" aria-hidden="true">✳</span><h2>A little clarity for your next project.</h2><p>Create your first project, work out the price, and bring the scope and schedule into one place.</p><button class="primary" data-action="new">Create your first project</button></div>')+'<div class="projects-tools"><p>Projects save on this device. Sign in to your workspace to keep them across devices.</p><div><button data-action="export">Export backup ↓</button><button data-action="import">Import backup ↑</button></div></div></section>';
 $('#save-state').textContent=storageOK?'Your workspace · saved on this device':'Storage unavailable · export a backup';
}
function createProject(){
 const today=new Date();const start=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
 open('A new project',field('title','Project name','text','','maxlength="200"')+field('client','Client','text','','maxlength="200"')+field('description','A short description','textarea','')+field('start','Kick-off date','date',start)+'<p class="hint">Start with the basics. Add the fee, deliverables and terms inside your project.</p>',async data=>{
  try{const next=newProject(Object.fromEntries(data));projects.unshift(next);p=next;view='project';save();dialog.close();toast('Project created.');if(workspace?.cloud.user){try{await workspace.save();toast('Project created and saved to cloud.');}catch(e){toast('Project saved on this device. '+e.message);}}}catch(e){toast(e.message);}
 },'Create project ↗');
}

document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.stage!==undefined){const s=stages(p)[Number(button.dataset.stage)];open(s.name,`<span class="stage-owner">${esc(s.owner)}</span><p class="hint">${date(s.start)}${s.start!==s.end?' — '+date(s.end):''}</p><div class="stage-detail" style="white-space:pre-line">${esc(s.body)}</div>`,null);return}if(button.dataset.project!==undefined&&!readonly){p=projects[Number(button.dataset.project)];view='project';preview=false;if(dialog.open)dialog.close();render();window.scrollTo(0,0);return}const a=button.dataset.action;if(a==='agreement'){showAgreement();return}if(a==='back-project'){closeAgreement();return}if(a==='download-agreement'){downloadAgreement();return}if(readonly)return;if(a==='preview'){preview=!preview;render()}else if(a==='share')share();else if(a==='projects')projectList();else if(a==='new')createProject();else if(a==='export')download('seabird-projects-backup.json',JSON.stringify(projects,null,2));else if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const file=input.files[0];if(file.size>2000000)throw Error();const items=JSON.parse(await file.text());if(!Array.isArray(items)||!items.length||items.length>100||!items.every(validate))throw Error();for(const item of items){projects.push({...item,id:crypto.randomUUID(),rate:Number(item.rate)||0,days:Number(item.days)||1,costs:Number(item.costs)||0})}view='projects';save();if(dialog.open)dialog.close();toast('Backup imported')}catch{toast('This file is not a valid Seabird project backup.')}};input.click()}else if(a)edit(a)});
$('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('hashchange',()=>location.reload());render();if(!readonly)save();

function editDeliverables(){
  const itemFields=(v)=>'<div class="deliverable-editor"><label>Item name<input class="item-name" maxlength="200" required value="'+esc(v.name)+'" placeholder="Opening title sequence — 4K master"></label><label>Technical specifications<textarea class="item-specs" maxlength="2000" placeholder="Resolution, frame rate, pixel aspect, codec / compression, colour space…">'+esc(v.specs)+'</textarea></label><button type="button" class="remove-deliverable">Remove item</button></div>';
  open('The deliverables','<p class="hint">Name each item, then add its delivery specifications. For video: square pixels, 4:2:2, Rec.709, plus resolution, frame rate and codec as needed.</p><div id="deliverable-editors">'+deliverableItems(p).map(itemFields).join('')+'</div><button type="button" id="add-deliverable">+ Add item</button>',()=>{
    const items=Array.from(document.querySelectorAll('.deliverable-editor'),el=>({name:el.querySelector('.item-name').value.trim(),specs:el.querySelector('.item-specs').value.trim()}));
    const next={...p,deliverableItems:items,deliverables:items.map(v=>v.name).join('\n')};
    if(!validate(next)){toast('Add at least one named deliverable, up to 30 items.');return}
    Object.assign(p,next);save();dialog.close();toast('Deliverables updated');
  });
  $('#add-deliverable').onclick=()=>{if(document.querySelectorAll('.deliverable-editor').length>=30){toast('You can add up to 30 items.');return}$('#deliverable-editors').insertAdjacentHTML('beforeend',itemFields({name:'',specs:''}));$('#deliverable-editors').lastElementChild.querySelector('input').focus()};
  $('#deliverable-editors').onclick=e=>{if(e.target.closest('.remove-deliverable'))e.target.closest('.deliverable-editor').remove()};
}


let agreementRequest=0,agreementSnapshot=null,agreementIssued=null;
function showAgreement(){
 agreementRequest++;agreementSnapshot=structuredClone(p);agreementIssued=sharedRecord?new Date(sharedRecord.published_at):new Date();
 $('#actions').innerHTML='<button data-action="back-project">← Back to project</button><button class="primary" data-action="download-agreement">Download PDF ↓</button>';
 $('#app').innerHTML='<section class="agreement-view"><div class="agreement-intro"><span class="section-label">THE COMPLETE PICTURE</span><h1>Your project, on paper.</h1><p>Review the full agreement below. Download a PDF when you are ready to email it for signing.</p><p class="hint">The PDF uses the same content and styling, with page breaks for printing.</p></div>'+agreementHtml(agreementSnapshot,agreementIssued)+'</section>';
 window.scrollTo(0,0);
}
function closeAgreement(){agreementRequest++;agreementSnapshot=null;render();window.scrollTo(0,0)}
async function downloadAgreement(){
 if(!agreementSnapshot)return;const request=agreementRequest,button=$('[data-action="download-agreement"]');if(button.disabled)return;
 button.disabled=true;button.textContent='Making PDF…';
 try{const snapshot=agreementSnapshot;const blob=await agreementBlob(snapshot,agreementIssued);if(request!==agreementRequest)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(snapshot.title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'project')+'-agreement.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
 catch{if(request===agreementRequest)toast('Could not generate the PDF. Please try again.')}
 finally{if(request===agreementRequest){button.disabled=false;button.textContent='Download PDF ↓'}}
}
document.addEventListener('toggle',e=>{if(e.target.matches('.project-card')&&e.target.open)document.querySelectorAll('.project-card').forEach(card=>{if(card!==e.target)card.open=false})},true);

if(!readonly)workspace=mountCloud({getProjects:()=>projects,setAccount,validate,setProjects:items=>{projects=items;p=projects[0];save();}});
